--############
--## RULES ###
--############
-- Port des window-rule / layer-rule de Niri (config.kdl)

-- --- Picture-in-Picture (YouTube, etc) ---
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.window_rule({
    name = "pip-window",
    match = {
        title = "^(Picture-in-Picture)$",
    },
    float = true,
    pin = true,
    no_shadow = true,
    size = "600 340",
    move = "100%-w-20 100%-h-20",
    no_initial_focus = true,
})

-- --- Ignore maximize requests from all apps ---
hl.window_rule({
    name = "suppress-maximize-events",
    match = {
        class = ".*",
    },
    suppress_event = "maximize",
})

-- --- Fix some dragging issues with XWayland ---
hl.window_rule({
    name = "fix-xwayland-drags",
    match = {
        class = "^$",
        title = "^$",
        xwayland = true,
        float = true,
        fullscreen = false,
        pin = false,
    },
    no_focus = true,
})

-- --- Niri : title "^BlackArch - " -> float min 900x600 ---
hl.window_rule({
    name = "blackarch-hud",
    match = {
        title = "^BlackArch -",
    },
    float = true,
    size = "900 600",
})

-- --- Niri : blueman / portal gtk -> float ---
hl.window_rule({
    name = "float-blueman-portal",
    match = {
        class = "^(blueman-manager|xdg-desktop-portal-gtk)$",
    },
    float = true,
})

-- --- Niri : pavucontrol / easyeffects -> ouverture maximisée (tuilée) ---
-- Pas de règle "maximize à l'ouverture" sous Hyprland : les fenêtres arrivent
-- tuilées, Super+F (fullscreen 1) maximise avec les gaps.
hl.window_rule({
    name = "tile-mixer",
    match = {
        class = "^(pavucontrol|org\\.pulseaudio\\.pavucontrol|com\\.github\\.wwmm\\.easyeffects)$",
    },
    float = false,
})

-- --- Niri : boîtes de dialogue de fichiers -> float ---
hl.window_rule({
    name = "float-file-dialogs",
    match = {
        title = "^(Open File|Enregistrer|Save As|Ouvrir)",
    },
    float = true,
})

-- --- Niri : tray-box (zone de notification) -> float collé en haut à droite ---
hl.window_rule({
    name = "tray-box",
    match = {
        class = "^tray-box$",
        title = "^Zone de notification$",
    },
    float = true,
    move = "100%-w-14 44",
})

-- --- Niri : panel Claude (flottant, collé à droite ; taille gérée par le script) ---
hl.window_rule({
    name = "claude-panel",
    match = {
        class = "^claude-panel$",
    },
    float = true,
    move = "100%-w-16 16",
})

-- =============================================================================
-- LAYER RULES (blur des surfaces quickshell)
-- =============================================================================
hl.layer_rule({
    name = "waybar-blur",
    match = {
        namespace = "waybar",
    },
    blur = true,
    ignore_alpha = 0.2,
})

hl.layer_rule({
    name = "apple-dock",
    match = {
        namespace = "apple-dock",
    },
    blur = true,
    ignore_alpha = 0.2,
})

hl.layer_rule({
    name = "swaync-cc",
    match = {
        namespace = "swaync-control-center",
    },
    blur = true,
    ignore_alpha = 0.5,
})

hl.layer_rule({
    name = "swaync-notif",
    match = {
        namespace = "swaync-notification-window",
    },
    blur = true,
    ignore_alpha = 0.5,
})

hl.layer_rule({
    name = "spell-blur",
    match = {
        namespace = "^(dashboard|ai|vm|scripts)$",
    },
    blur = true,
    ignore_alpha = 0.4,
})

hl.layer_rule({
    name = "rofi-blur",
    match = {
        namespace = "rofi",
    },
    blur = true,
    ignore_alpha = 0.3,
})

hl.layer_rule({
    name = "overview-blur",
    match = {
        namespace = "catalyst-overview",
    },
    blur = true,
    ignore_alpha = 0.3,
})

-- Niri : catalyst-atelier a un background-effect blur
hl.layer_rule({
    name = "catalyst-atelier-blur",
    match = {
        namespace = "catalyst-atelier",
    },
    blur = true,
    ignore_alpha = 0.1,
})

-- Tsubasa Catalyst v3 — surfaces Quickshell (flou derrière le verre uniquement :
-- ignore_alpha exclut ombres et zones transparentes des fenêtres plein écran)
hl.layer_rule({
    name = "catalyst-v3-blur",
    match = {
        namespace = "^(catalyst-bar|catalyst-stage|catalyst-dock|catalyst-notif|catalyst-osd)$",
    },
    blur = true,
    ignore_alpha = 0.5,
})

-- Le flou ne s'applique qu'aux surfaces ciblées : jamais aux fenêtres
hl.window_rule({
    name = "catalyst-no-window-blur",
    match = {
        class = ".*",
    },
    no_blur = true,
})

-- Terminal déroulant (Super+`) : workspace spécial « term », Alacritty créé
-- à la première ouverture puis conservé (masqué/affiché instantanément)
hl.workspace_rule({
    workspace = "special:term",
    on_created_empty = "alacritty --class catalyst-term",
    gaps_out = 60,
})

